// Jhave's Poetry Slam - click lines from Jhave's writing to perform at open mic night.
// All poem lines are verbatim from https://glia.ca/ by David Jhave Johnston (CC BY-NC-SA 4.0).
(() => {
  'use strict';

  const SET_LENGTH = 55;        // seconds until you win, no matter what
  const FINALE_HOLD = 6;        // seconds of applause before reporting to the host
  const STRIPS_ON_SCREEN = 6;
  const FACE_JAW = 0.765;        // where the photo is split for the flapping jaw (0..1 of height)

  const LINES = [
    'Stop seeking. You are it.',
    'Lucidity is a language to itself.',
    'Humanity is out of credits.',
    'Memory ferments.',
    'Begin bloom-scrolling.',
    'Prompt-engineer enlightenment.',
    'Long live narrative.',
    "We're entering a riptide.",
    "Even the quantum decoherence won't save them.",
    'You are a story.',
    'Set aside ancient forces.',
    'Forgive it all.',
    'Stay joyous.',
    'Consider the upgrade paradox.',
    'A seed of hope in a sea of shit.',
    'When the ineffable becomes algorithmically tractable.',
    'When the Merge comes it will feel normal.',
    'Hallucinations are (almost) all you need.',
    'Neanderthals met Sapiens.',
    'Nothing generated was thrown away.',
    'Trusting the machine, letting the algorithm lead.',
    'Setting aside ownership of aesthetic judgements.',
    'Parables for a disintegrative era with extreme potential.',
    "Please, don't be afraid. We're not here to harvest you.",
    'Not a god. Not a name.',
    'Gather filter actuate repeat.',
    'They hallucinate, filter, synthesize, optimize, repeat.',
    'This is an epistemological explosion.',
    'This is the age of murmuration.',
    'We are no longer the only dreamers.',
    'A tuning of the ear to something quieter.',
    'Let us construct not just content, but communion.',
    'To the murmuring beneath the noise.',
    'What follows is not an argument.',
    'The revolution will have a link in bio.',
    'The picket line is now a pixel grid, my friend.',
    'The revolution will have an affiliate code for a fair-trade coffee shop.',
    'It is music made not for you, but from you.',
    'Everything we see is vibration.',
    'Imagine a concert that begins empty.',
    'Generated by a computer. Edited by a human.',
    'An evocative, infinite deep-learning muse.',
    'Unsubscribe from the sorrow stream.',
    'Crease the old map.',
    'Erase the old trail.',
    'Home in the loving kitsch.',
    'Trauma in a tote bag.',
    'Is this the labyrinth?',
    'It grows until it breaks.',
    'A pointer to null space.',
    'And the air finally gives.',
    'Measure a position, you lose the pace.',
    'Far below in the scroll moss.',
    'A soft & cozy glitch in the lens.',
    'New discourse just dropped.',
    'I am cinders scattering departures exactly guided.',
    'We tasted the meaning of houses.',
    'The peace of an animal.',
    'A body which is not but is.',
    'Taking on cosmic light.',
    'Free joy & gentleness.',
    'Be reared away, magnolias.',
    'Act not. Stim in. Feel all.',
    'Sun bleeds orange.',
    'Just saying hello.'
  ];

  // ---- DOM ----
  const canvas = document.getElementById('stage');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const tray = $('tray');
  const clockEl = $('clock');
  const clapsEl = $('claps');
  const hissesEl = $('hisses');
  const titleCard = $('title-card');
  const finaleEl = $('finale');
  const sayEl = $('say');
  const standalone = window.parent === window;
  if (standalone) $('start-hint').innerHTML = 'Click anywhere to take the stage';

  let W = 0, H = 0, DPR = 1;
  let backdrop = null;

  // ---- Faces: real photo if provided, cartoon fallback otherwise ----
  const faces = { smile: null, grimace: null, photo: false };

  function loadImage(src) {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = () => resolve(null);
      img.src = src;
    });
  }

  async function loadFaces() {
    const smile = (await loadImage('./faces/jhave.png')) || (await loadImage('./faces/jhave.jpg'));
    const grimace = (await loadImage('./faces/jhave-grimace.png')) || (await loadImage('./faces/jhave-grimace.jpg'));
    if (smile) {
      faces.smile = smile;
      faces.grimace = grimace || smile;
      faces.photo = true;
    }
  }

  function cartoonFace(grimace) {
    const c = document.createElement('canvas');
    c.width = 400; c.height = 480;
    const g = c.getContext('2d');
    g.lineWidth = 10;
    g.strokeStyle = '#1c1208';
    g.lineJoin = 'round';
    // ears
    g.fillStyle = '#f1b98f';
    for (const s of [-1, 1]) {
      g.beginPath(); g.ellipse(200 + s * 170, 250, 34, 50, 0, 0, Math.PI * 2); g.fill(); g.stroke();
    }
    // face
    g.beginPath(); g.ellipse(200, 240, 165, 215, 0, 0, Math.PI * 2); g.fill(); g.stroke();
    // hair
    g.fillStyle = '#b9b2a6';
    g.beginPath();
    g.ellipse(200, 92, 132, 58, 0, Math.PI, 0);
    g.fill();
    // brows
    g.lineWidth = 12;
    for (const s of [-1, 1]) {
      g.beginPath();
      if (grimace) { g.moveTo(200 + s * 40, 175); g.lineTo(200 + s * 120, 155); }
      else { g.moveTo(200 + s * 40, 168); g.quadraticCurveTo(200 + s * 85, 145, 200 + s * 125, 165); }
      g.stroke();
    }
    // glasses + eyes
    g.lineWidth = 9;
    g.strokeStyle = '#a9b4bd';
    for (const s of [-1, 1]) {
      g.fillStyle = '#ffffff';
      g.beginPath(); g.ellipse(200 + s * 80, 220, 52, 42, 0, 0, Math.PI * 2); g.fill(); g.stroke();
      g.fillStyle = '#1c1208';
      g.beginPath(); g.arc(200 + s * 76 + (grimace ? s * 8 : 0), 222, grimace ? 9 : 14, 0, Math.PI * 2); g.fill();
    }
    g.beginPath(); g.moveTo(172, 214); g.quadraticCurveTo(200, 200, 228, 214); g.stroke();
    g.strokeStyle = '#1c1208';
    // nose
    g.lineWidth = 8;
    g.beginPath(); g.moveTo(200, 250); g.quadraticCurveTo(185, 300, 205, 305); g.stroke();
    // mouth (below the jaw split it will flap)
    g.lineWidth = 9;
    if (grimace) {
      g.fillStyle = '#ffffff';
      g.beginPath(); g.roundRect(130, 345, 140, 46, 14); g.fill(); g.stroke();
      for (let k = 1; k < 5; k++) { g.beginPath(); g.moveTo(130 + k * 28, 345); g.lineTo(130 + k * 28, 391); g.stroke(); }
      g.beginPath(); g.moveTo(130, 368); g.lineTo(270, 368); g.stroke();
    } else {
      g.fillStyle = '#7a1f1f';
      g.beginPath(); g.moveTo(125, 335); g.quadraticCurveTo(200, 420, 275, 335); g.closePath(); g.fill(); g.stroke();
    }
    // stubble dots
    g.fillStyle = 'rgba(150,145,135,0.55)';
    for (let k = 0; k < 120; k++) {
      const a = Math.random() * Math.PI, r = 120 + Math.random() * 70;
      const x = 200 + Math.cos(a) * r * 0.85, y = 300 + Math.sin(a) * r * 0.75;
      if (y > 320) g.fillRect(x, y, 3, 3);
    }
    return c;
  }

  // ---- Layout & backdrop ----
  function resize() {
    DPR = Math.min(2, window.devicePixelRatio || 1);
    W = window.innerWidth;
    H = window.innerHeight;
    canvas.width = Math.round(W * DPR);
    canvas.height = Math.round(H * DPR);
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
    buildBackdrop();
  }

  function ink(g, w = 3) {
    g.lineWidth = w;
    g.strokeStyle = '#1c1208';
    g.lineJoin = 'round';
    g.lineCap = 'round';
  }

  function buildBackdrop() {
    backdrop = document.createElement('canvas');
    backdrop.width = canvas.width;
    backdrop.height = canvas.height;
    const g = backdrop.getContext('2d');
    g.setTransform(DPR, 0, 0, DPR, 0, 0);

    // brick wall
    g.fillStyle = '#7e3420';
    g.fillRect(0, 0, W, H);
    const bh = Math.max(16, H / 38), bw = bh * 2.6;
    for (let row = 0, y = 0; y < H; row++, y += bh) {
      for (let x = (row % 2) * -bw / 2; x < W; x += bw) {
        const shade = 110 + ((row * 7 + Math.floor(x / bw) * 13) % 5) * 9;
        g.fillStyle = `rgb(${shade + 20},${shade / 2.2 | 0},${shade / 3.4 | 0})`;
        g.fillRect(x + 2, y + 2, bw - 4, bh - 4);
      }
    }
    // warm vignette
    const vg = g.createRadialGradient(W / 2, H * 0.45, H * 0.1, W / 2, H * 0.45, Math.max(W, H) * 0.8);
    vg.addColorStop(0, 'rgba(0,0,0,0)');
    vg.addColorStop(1, 'rgba(30,10,0,0.65)');
    g.fillStyle = vg;
    g.fillRect(0, 0, W, H);

    // chalkboard sign
    if (W > 720) {
      const cw = Math.min(260, W * 0.2), ch = cw * 0.95, cx = W * 0.8, cy = H * 0.36;
      g.fillStyle = '#6b4a2b';
      ink(g, 4);
      g.beginPath(); g.roundRect(cx - cw / 2 - 10, cy - ch / 2 - 10, cw + 20, ch + 20, 8); g.fill(); g.stroke();
      g.fillStyle = '#26342b';
      g.fillRect(cx - cw / 2, cy - ch / 2, cw, ch);
      g.fillStyle = '#f2efe6';
      g.textAlign = 'center';
      g.font = `bold ${cw * 0.13}px "Chalkboard SE", "Comic Sans MS", cursive`;
      g.fillText('OPEN MIC', cx, cy - ch * 0.26);
      g.font = `${cw * 0.1}px "Chalkboard SE", "Comic Sans MS", cursive`;
      g.fillStyle = '#ffd23f';
      g.fillText('★ POETRY ★', cx, cy - ch * 0.06);
      g.fillStyle = '#f2efe6';
      g.fillText('tonite!', cx, cy + ch * 0.1);
      g.font = `${cw * 0.075}px "Chalkboard SE", "Comic Sans MS", cursive`;
      g.fillStyle = '#9fe3dc';
      g.fillText('oat-milk pour-over $9', cx, cy + ch * 0.3);
    }

    // framed art (left)
    if (W > 720) {
      const fw = Math.min(170, W * 0.13), fx = W * 0.15, fy = H * 0.34;
      g.fillStyle = '#f5a300';
      ink(g, 4);
      g.fillRect(fx - fw / 2, fy - fw * 0.6, fw, fw * 1.2);
      g.strokeRect(fx - fw / 2, fy - fw * 0.6, fw, fw * 1.2);
      g.fillStyle = '#fffbea';
      g.fillRect(fx - fw / 2 + 10, fy - fw * 0.6 + 10, fw - 20, fw * 1.2 - 20);
      // abstract "glia" squiggle
      g.strokeStyle = '#1aa39a'; g.lineWidth = 6;
      g.beginPath();
      for (let k = 0; k < 40; k++) {
        const t = k / 39;
        g.lineTo(fx - fw * 0.35 + t * fw * 0.7, fy + Math.sin(t * 12) * fw * 0.25 * (1 - t));
      }
      g.stroke();
      g.fillStyle = '#e8452c';
      g.beginPath(); g.arc(fx + fw * 0.15, fy - fw * 0.3, fw * 0.12, 0, Math.PI * 2); g.fill();
    }

    // stage floor
    const floorY = H * 0.74;
    g.fillStyle = '#6b3f21';
    g.fillRect(0, floorY, W, H - floorY);
    g.strokeStyle = 'rgba(30,15,5,0.5)';
    g.lineWidth = 2;
    for (let y = floorY + 14; y < H; y += 18) { g.beginPath(); g.moveTo(0, y); g.lineTo(W, y); g.stroke(); }
    ink(g, 4);
    g.beginPath(); g.moveTo(0, floorY); g.lineTo(W, floorY); g.stroke();
    // rug
    g.fillStyle = '#b8324a';
    g.beginPath(); g.ellipse(W / 2, floorY + H * 0.03, W * 0.2, H * 0.03, 0, 0, Math.PI * 2); g.fill(); g.stroke();
    g.strokeStyle = '#ffd23f'; g.lineWidth = 3;
    g.beginPath(); g.ellipse(W / 2, floorY + H * 0.03, W * 0.16, H * 0.02, 0, 0, Math.PI * 2); g.stroke();

    // monstera plant (left)
    const px = W * 0.08, py = floorY;
    g.fillStyle = '#c8643a'; ink(g, 4);
    g.beginPath(); g.moveTo(px - 34, py); g.lineTo(px + 34, py); g.lineTo(px + 26, py - 60); g.lineTo(px - 26, py - 60); g.closePath(); g.fill(); g.stroke();
    g.fillStyle = '#2e8b4e';
    for (let k = 0; k < 6; k++) {
      const a = -Math.PI / 2 + (k - 2.5) * 0.45;
      const lx = px + Math.cos(a) * 80, ly = py - 70 + Math.sin(a) * 80;
      g.beginPath(); g.ellipse(lx, ly, 34, 22, a, 0, Math.PI * 2); g.fill(); g.stroke();
      g.beginPath(); g.moveTo(px, py - 60); g.lineTo(lx, ly); g.stroke();
    }
  }

  // ---- Characters ----
  const jhave = { talk: 0, jaw: 0, mood: 'smile', moodT: 0, gesture: 0 };
  const HIPSTERS = [
    { hair: '#2b1d14', hat: 'beret', hatColor: '#b8324a', sweater: '#d98e04', skin: '#c68a5e' },
    { hair: '#e0c068', hat: 'bun', sweater: '#4f7a5b', skin: '#f1c7a5', scarf: '#e8452c' },
    { hair: '#3a2a20', hat: 'beanie', hatColor: '#1aa39a', sweater: '#6c4a8c', skin: '#8d5a3b' },
    { hair: '#141414', hat: 'headphones', sweater: '#c7b8a1', skin: '#e8b48f' },
    { hair: '#a8462a', hat: 'long', sweater: '#2f4f6f', skin: '#f3d0b5', scarf: '#ffd23f' },
    { hair: '#5b4632', hat: 'beret', hatColor: '#1c1208', sweater: '#9c3d2e', skin: '#d9a07a' },
    { hair: '#d8d0c0', hat: 'bun', sweater: '#3b6b6b', skin: '#b67a52' }
  ].map((h, i) => ({ ...h, phase: i * 1.3, react: null }));

  let crowd = null;            // { type: 'clap'|'hiss', t, who: Set }
  let captions = [];           // floating text pops
  let confetti = [];

  function limb(x1, y1, x2, y2, w, color) {
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#1c1208';
    ctx.lineWidth = w + 6;
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
    ctx.strokeStyle = color;
    ctx.lineWidth = w;
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  }

  function drawJhave(t) {
    const floorY = H * 0.74;
    const S = Math.min(H / 800, W / 700);
    const x = W / 2;
    const feetY = floorY + H * 0.02;
    const hipY = feetY - 120 * S;
    const shoulderY = hipY - 120 * S;
    const bobble = Math.round(Math.sin(t * (jhave.talk > 0 ? 9 : 2.4)) * 2) * 2 * S; // jerky cut-out bob

    // mic stand
    const micX = x - 95 * S;
    ink(ctx, 4);
    ctx.strokeStyle = '#1c1208';
    ctx.beginPath(); ctx.moveTo(micX - 30 * S, feetY); ctx.lineTo(micX + 30 * S, feetY); ctx.stroke();
    limb(micX, feetY, micX, shoulderY + 30 * S, 4 * S, '#8a8f99');
    limb(micX, shoulderY + 30 * S, micX + 30 * S, shoulderY + 6 * S, 4 * S, '#8a8f99');

    // legs
    limb(x - 22 * S, hipY, x - 30 * S, feetY - 8 * S, 26 * S, '#2b3a67');
    limb(x + 22 * S, hipY, x + 30 * S, feetY - 8 * S, 26 * S, '#2b3a67');
    ctx.fillStyle = '#1c1208';
    ctx.beginPath(); ctx.ellipse(x - 40 * S, feetY - 4 * S, 24 * S, 10 * S, 0, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(x + 40 * S, feetY - 4 * S, 24 * S, 10 * S, 0, 0, Math.PI * 2); ctx.fill();

    // arms (2-frame gestures while talking)
    const frame = jhave.talk > 0 ? Math.floor(t * 4) % 2 : 0;
    const handR = frame
      ? [x + 110 * S, shoulderY - 70 * S]
      : jhave.talk > 0 ? [x + 120 * S, shoulderY + 10 * S] : [x + 70 * S, hipY + 10 * S];
    limb(x + 52 * S, shoulderY + 12 * S, handR[0], handR[1], 22 * S, '#45484e');
    ctx.fillStyle = '#f1b98f'; ink(ctx, 3);
    ctx.beginPath(); ctx.arc(handR[0], handR[1], 12 * S, 0, Math.PI * 2); ctx.fill(); ctx.stroke();

    // torso: open charcoal overshirt over a mustard tee
    ctx.fillStyle = '#45484e'; ink(ctx, 4);
    ctx.beginPath();
    ctx.moveTo(x - 60 * S, shoulderY);
    ctx.lineTo(x + 60 * S, shoulderY);
    ctx.lineTo(x + 50 * S, hipY + 14 * S);
    ctx.lineTo(x - 50 * S, hipY + 14 * S);
    ctx.closePath(); ctx.fill(); ctx.stroke();
    ctx.fillStyle = '#f2a516'; ink(ctx, 3);
    ctx.beginPath();
    ctx.moveTo(x - 26 * S, shoulderY); ctx.lineTo(x + 26 * S, shoulderY);
    ctx.lineTo(x + 20 * S, hipY + 14 * S); ctx.lineTo(x - 20 * S, hipY + 14 * S);
    ctx.closePath(); ctx.fill(); ctx.stroke();
    ctx.beginPath(); ctx.arc(x, shoulderY - 2 * S, 16 * S, 0.15 * Math.PI, 0.85 * Math.PI); ctx.stroke();
    // collar points and buttons on the overshirt
    ctx.fillStyle = '#45484e';
    for (const sd of [-1, 1]) {
      ctx.beginPath(); ctx.moveTo(x + sd * 26 * S, shoulderY - 4 * S); ctx.lineTo(x + sd * 48 * S, shoulderY - 6 * S); ctx.lineTo(x + sd * 30 * S, shoulderY + 22 * S); ctx.closePath(); ctx.fill(); ctx.stroke();
    }
    ctx.fillStyle = '#1c1208';
    for (let k = 0; k < 4; k++) { ctx.beginPath(); ctx.arc(x - 31 * S, shoulderY + (30 + k * 26) * S, 2.5 * S, 0, Math.PI * 2); ctx.fill(); }

    // left arm holds the notebook
    limb(x - 52 * S, shoulderY + 12 * S, x - 40 * S, shoulderY + 70 * S, 22 * S, '#45484e');
    ctx.save();
    ctx.translate(x - 30 * S, shoulderY + 64 * S);
    ctx.rotate(-0.15);
    ctx.fillStyle = '#fffbea'; ink(ctx, 3);
    ctx.fillRect(-26 * S, -34 * S, 52 * S, 64 * S);
    ctx.strokeRect(-26 * S, -34 * S, 52 * S, 64 * S);
    ctx.strokeStyle = '#7fb3d5'; ctx.lineWidth = 1.5;
    for (let k = 0; k < 5; k++) { ctx.beginPath(); ctx.moveTo(-20 * S, (-22 + k * 11) * S); ctx.lineTo(20 * S, (-22 + k * 11) * S); ctx.stroke(); }
    ctx.restore();
    ctx.fillStyle = '#f1b98f'; ink(ctx, 3);
    ctx.beginPath(); ctx.arc(x - 40 * S, shoulderY + 70 * S, 12 * S, 0, Math.PI * 2); ctx.fill(); ctx.stroke();

    // mic head in front of the face
    // head
    const headW = 150 * S, headH = 180 * S;
    let hx = x, hy = shoulderY - headH * 0.46 + bobble;
    let tilt = 0, squash = 1;
    const mt = jhave.moodT;
    if (mt > 0 && jhave.mood === 'grimace') {
      hx += Math.sin(t * 60) * 4 * S;
      tilt = -0.12;
      squash = 0.94;
    } else if (mt > 0) {
      hy -= Math.abs(Math.sin(t * 10)) * 10 * S;
      tilt = Math.sin(t * 6) * 0.08;
    }
    drawHead(hx, hy, headW, headH * squash, tilt);

    ctx.fillStyle = '#4a4f59'; ink(ctx, 3);
    ctx.beginPath(); ctx.ellipse(micX + 36 * S, shoulderY - 2 * S, 12 * S, 16 * S, -0.7, 0, Math.PI * 2); ctx.fill(); ctx.stroke();

    // mood extras
    if (mt > 0 && jhave.mood === 'grimace') {
      for (let k = 0; k < 3; k++) {
        const dx = hx + headW * 0.55 + k * 10 * S, dy = hy - headH * 0.2 + ((t * 120 + k * 30) % 60) * S;
        ctx.fillStyle = '#9fe3ff'; ink(ctx, 2);
        ctx.beginPath(); ctx.moveTo(dx, dy - 10 * S); ctx.quadraticCurveTo(dx + 8 * S, dy + 4 * S, dx, dy + 6 * S); ctx.quadraticCurveTo(dx - 8 * S, dy + 4 * S, dx, dy - 10 * S); ctx.fill(); ctx.stroke();
      }
    } else if (mt > 0) {
      for (let k = 0; k < 3; k++) {
        const a = t * 3 + k * 2.1;
        star(hx + Math.cos(a) * headW * 0.8, hy - headH * 0.35 + Math.sin(a) * 20 * S, 9 * S, '#ffd23f');
      }
    }
    return { hx, hy, headW, headH, S };
  }

  function star(x, y, r, color) {
    ctx.fillStyle = color; ink(ctx, 2);
    ctx.beginPath();
    for (let k = 0; k < 10; k++) {
      const rr = k % 2 ? r * 0.45 : r, a = -Math.PI / 2 + k * Math.PI / 5;
      ctx.lineTo(x + Math.cos(a) * rr, y + Math.sin(a) * rr);
    }
    ctx.closePath(); ctx.fill(); ctx.stroke();
  }

  // JibJab-style: cut-out face with a white paper edge, jaw split and flapping
  function drawHead(x, y, w, h, tilt) {
    const img = jhave.mood === 'grimace' && jhave.moodT > 0 ? faces.grimace : faces.smile;
    if (!img) return;
    const open = jhave.jaw * h * 0.12;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(tilt);
    // paper edge + outline
    ctx.fillStyle = '#ffffff';
    ink(ctx, 3);
    ctx.beginPath(); ctx.ellipse(0, open / 2, w / 2 + 7, h / 2 + 7 + open / 2, 0, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    const jawY = -h / 2 + h * FACE_JAW;
    // dark mouth gap
    if (open > 0.5) {
      ctx.fillStyle = '#3b0d0d';
      ctx.beginPath(); ctx.ellipse(0, jawY + open / 2, w * 0.28, open / 2 + 2, 0, 0, Math.PI * 2); ctx.fill();
    }
    const clipEllipse = (dy) => { ctx.beginPath(); ctx.ellipse(0, dy, w / 2, h / 2, 0, 0, Math.PI * 2); };
    // upper face
    ctx.save();
    clipEllipse(0); ctx.clip();
    ctx.beginPath(); ctx.rect(-w, -h, w * 2, jawY + h); ctx.clip();
    ctx.drawImage(img, -w / 2, -h / 2, w, h);
    ctx.restore();
    // jaw
    ctx.save();
    ctx.translate(0, open);
    clipEllipse(0); ctx.clip();
    ctx.beginPath(); ctx.rect(-w, jawY, w * 2, h); ctx.clip();
    ctx.drawImage(img, -w / 2, -h / 2, w, h);
    ctx.restore();
    ctx.restore();
  }

  function drawHipster(hp, x, y, r, t) {
    const react = crowd && crowd.who.has(hp) ? crowd.type : null;
    const bounce = react === 'clap' ? Math.abs(Math.sin(t * 14 + hp.phase)) * 6 : Math.sin(t * 1.5 + hp.phase) * 2;
    const turn = react === 'hiss' ? 0.35 : 0;
    y -= bounce;
    // shoulders / sweater
    ctx.fillStyle = hp.sweater; ink(ctx, 4);
    ctx.beginPath(); ctx.ellipse(x, y + r * 1.5, r * 1.6, r * 1.0, 0, Math.PI, 0); ctx.lineTo(x + r * 1.6, H + 10); ctx.lineTo(x - r * 1.6, H + 10); ctx.closePath(); ctx.fill(); ctx.stroke();
    if (hp.scarf) {
      ctx.fillStyle = hp.scarf;
      ctx.beginPath(); ctx.ellipse(x, y + r * 0.85, r * 0.75, r * 0.3, 0, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    }
    // head from behind (turns a little to hiss)
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(turn * 0.4);
    if (hp.hat === 'long') {
      ctx.fillStyle = hp.hair;
      ctx.beginPath(); ctx.roundRect(-r * 1.05, -r * 0.2, r * 2.1, r * 1.5, r * 0.6); ctx.fill(); ctx.stroke();
    }
    if (turn) {
      // a sliver of profile: nose and pursed lips
      ctx.fillStyle = hp.skin;
      ctx.beginPath(); ctx.ellipse(r * 0.75, r * 0.05, r * 0.35, r * 0.55, 0, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(r * 1.0, -r * 0.1); ctx.lineTo(r * 1.25, r * 0.12); ctx.lineTo(r * 1.0, r * 0.18); ctx.fill(); ctx.stroke();
    }
    ctx.fillStyle = hp.hair;
    ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    // ears
    ctx.fillStyle = hp.skin;
    for (const s of [-1, 1]) {
      if (hp.hat === 'long') continue;
      ctx.beginPath(); ctx.ellipse(s * r * 0.98, r * 0.1, r * 0.18, r * 0.28, 0, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    }
    switch (hp.hat) {
      case 'beret':
        ctx.fillStyle = hp.hatColor;
        ctx.beginPath(); ctx.ellipse(-r * 0.1, -r * 0.75, r * 1.0, r * 0.4, -0.25, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(-r * 0.15, -r * 1.1); ctx.lineTo(-r * 0.1, -r * 1.3); ctx.stroke();
        break;
      case 'beanie':
        ctx.fillStyle = hp.hatColor;
        ctx.beginPath(); ctx.arc(0, -r * 0.15, r * 1.02, Math.PI, 0); ctx.fill(); ctx.stroke();
        ctx.beginPath(); ctx.roundRect(-r * 1.05, -r * 0.3, r * 2.1, r * 0.35, 6); ctx.fill(); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, -r * 1.2, r * 0.22, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
        break;
      case 'bun':
        ctx.fillStyle = hp.hair;
        ctx.beginPath(); ctx.arc(0, -r * 1.05, r * 0.38, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
        break;
      case 'headphones':
        ctx.strokeStyle = '#e8452c'; ctx.lineWidth = 6;
        ctx.beginPath(); ctx.arc(0, -r * 0.05, r * 1.08, Math.PI * 1.05, Math.PI * 1.95); ctx.stroke();
        ctx.fillStyle = '#e8452c'; ink(ctx, 3);
        for (const s of [-1, 1]) { ctx.beginPath(); ctx.ellipse(s * r * 1.02, r * 0.1, r * 0.25, r * 0.38, 0, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); }
        break;
    }
    ctx.restore();

    // reaction props
    if (react === 'clap') {
      const k = Math.abs(Math.sin(t * 14 + hp.phase));
      const gap = 6 + k * 16;
      ctx.fillStyle = hp.skin; ink(ctx, 3);
      for (const s of [-1, 1]) {
        ctx.beginPath(); ctx.ellipse(x + s * gap, y - r * 1.6, r * 0.22, r * 0.36, s * 0.3, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      }
    } else if (react === 'hiss') {
      ctx.save();
      ctx.font = `bold ${r * 0.55}px "Comic Sans MS", cursive`;
      ctx.fillStyle = '#7ad151';
      ctx.strokeStyle = '#1c1208'; ctx.lineWidth = 3;
      const sx = x + r * 1.1, sy = y - r * 0.9 - ((t * 40 + hp.phase * 20) % 30);
      ctx.strokeText('sss', sx, sy);
      ctx.fillText('sss', sx, sy);
      ctx.restore();
    }
  }

  function drawCrowd(t) {
    const r = Math.max(26, Math.min(H * 0.065, W / 18));
    const n = HIPSTERS.length;
    HIPSTERS.forEach((hp, i) => {
      const x = W * (i + 0.5) / n + (i % 2 ? 10 : -10);
      const y = H - r * (i % 2 ? 1.3 : 0.9);
      drawHipster(hp, x, y, r, t);
    });
  }

  // ---- String lights & spotlight ----
  function drawLights(t) {
    const y0 = H * 0.07, sag = H * 0.06;
    ctx.strokeStyle = '#1c1208';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let x = 0; x <= W; x += 20) ctx.lineTo(x, y0 + Math.sin((x / W) * Math.PI) * sag);
    ctx.stroke();
    const colors = ['#ffd23f', '#ff8a5c', '#9fe3dc', '#ffd23f', '#f6a5c0'];
    let k = 0;
    for (let x = 30; x < W; x += 58, k++) {
      const y = y0 + Math.sin((x / W) * Math.PI) * sag + 10;
      const on = 0.75 + 0.25 * Math.sin(t * 3 + k * 1.7);
      const g = ctx.createRadialGradient(x, y, 0, x, y, 26);
      g.addColorStop(0, `rgba(255,220,140,${0.5 * on})`);
      g.addColorStop(1, 'rgba(255,220,140,0)');
      ctx.fillStyle = g;
      ctx.fillRect(x - 26, y - 26, 52, 52);
      ctx.fillStyle = colors[k % colors.length];
      ink(ctx, 2);
      ctx.beginPath(); ctx.ellipse(x, y, 6, 9, 0, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    }
  }

  function drawSpotlight() {
    const floorY = H * 0.74;
    const g = ctx.createLinearGradient(0, 0, 0, floorY);
    g.addColorStop(0, 'rgba(255,240,180,0.0)');
    g.addColorStop(1, 'rgba(255,240,180,0.22)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(W / 2 - 30, 0);
    ctx.lineTo(W / 2 + 30, 0);
    ctx.lineTo(W / 2 + Math.min(W * 0.22, 260), floorY + 20);
    ctx.lineTo(W / 2 - Math.min(W * 0.22, 260), floorY + 20);
    ctx.closePath();
    ctx.fill();
  }

  // ---- Speech bubble ----
  let bubble = null;           // { text, t }

  function drawBubble(head) {
    if (!bubble) return;
    const a = Math.min(1, bubble.t * 5);
    const size = Math.max(15, Math.min(22, W / 40));
    ctx.font = `bold ${size}px "Comic Sans MS", "Chalkboard SE", cursive`;
    const maxW = Math.min(280, W * 0.36);
    const words = bubble.text.split(' ');
    const lines = [];
    let line = '';
    for (const w of words) {
      const test = line ? `${line} ${w}` : w;
      if (ctx.measureText(test).width > maxW && line) { lines.push(line); line = w; } else line = test;
    }
    lines.push(line);
    const bw = Math.max(...lines.map((l) => ctx.measureText(l).width)) + 28;
    const bh = lines.length * size * 1.3 + 20;
    let bx = head.hx + head.headW * 0.55;
    if (bx + bw > W - 10) bx = Math.max(10, head.hx - head.headW * 0.55 - bw);
    const by = Math.min(H * 0.72 - bh, Math.max(10, head.hy - bh * 0.2));
    ctx.save();
    ctx.globalAlpha = a;
    ctx.fillStyle = '#fffbea';
    ink(ctx, 3);
    ctx.beginPath(); ctx.roundRect(bx, by, bw, bh, 16); ctx.fill(); ctx.stroke();
    // tail toward the mouth
    const left = bx < head.hx;
    const ty = by + Math.min(bh - 24, 18);
    const ex = left ? bx + bw - 2 : bx + 2;
    ctx.beginPath();
    ctx.moveTo(ex, ty);
    ctx.lineTo(head.hx + (left ? -head.headW * 0.3 : head.headW * 0.3), head.hy + head.headH * 0.18);
    ctx.lineTo(ex, ty + 18);
    ctx.fill(); ctx.stroke();
    ctx.fillStyle = '#1c1208';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    lines.forEach((l, i) => ctx.fillText(l, bx + 14, by + 10 + i * size * 1.3));
    ctx.restore();
  }

  function popCaption(text, color, size) {
    captions.push({ text, color, size, t: 0, x: W / 2 + (Math.random() - 0.5) * W * 0.2, y: H * 0.66 });
  }

  function drawCaptions(dt) {
    for (const c of captions) {
      c.t += dt;
      const a = Math.max(0, 1 - c.t / 1.6);
      const s = c.size * (1 + Math.min(0.2, c.t));
      ctx.save();
      ctx.globalAlpha = a;
      ctx.translate(c.x, c.y - c.t * 30);
      ctx.rotate(-0.06);
      ctx.font = `bold ${s}px "Cooper Black", "Bookman Old Style", Georgia, serif`;
      ctx.textAlign = 'center';
      ctx.lineJoin = 'round';
      ctx.lineWidth = 7;
      ctx.strokeStyle = '#1c1208';
      ctx.strokeText(c.text, 0, 0);
      ctx.fillStyle = c.color;
      ctx.fillText(c.text, 0, 0);
      ctx.restore();
    }
    captions = captions.filter((c) => c.t < 1.6);
  }

  // ---- Game state ----
  let state = 'waiting';       // waiting | play | finale | over
  let startAt = 0;
  let busy = false;
  let poem = [];
  let claps = 0, hisses = 0;
  let pool = [];
  let ended = false;
  let finaleAt = 0;
  let resultText = '';

  function shuffled(a) {
    const b = a.slice();
    for (let i = b.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [b[i], b[j]] = [b[j], b[i]]; }
    return b;
  }

  function nextLine() {
    if (!pool.length) pool = shuffled(LINES.filter((l) => !poem.includes(l)));
    return pool.pop() || LINES[Math.floor(Math.random() * LINES.length)];
  }

  function makeStrip(text) {
    const b = document.createElement('button');
    b.className = 'strip enter';
    b.type = 'button';
    b.textContent = text;
    b.style.setProperty('--rot', `${(Math.random() - 0.5) * 6}deg`);
    b.style.setProperty('--delay', `${-Math.random() * 2}s`);
    b.disabled = state !== 'play' || busy;
    b.addEventListener('click', () => perform(b));
    b.addEventListener('animationend', (e) => { if (e.animationName === 'pop-in') b.classList.remove('enter'); });
    return b;
  }

  function fillTray() {
    while (tray.children.length < STRIPS_ON_SCREEN) tray.appendChild(makeStrip(nextLine()));
  }

  function setBusy(v) {
    busy = v;
    for (const b of tray.children) b.disabled = v || state !== 'play';
  }

  function startGame() {
    if (state !== 'waiting') return;
    state = 'play';
    startAt = performance.now();
    titleCard.classList.add('gone');
    sfx.unlock();
    sfx.startBand();
    pool = shuffled(LINES);
    fillTray();
    setBusy(false);
    popCaption('Give it up for JHAVE!', '#ffd23f', Math.min(40, W / 16));
    sfx.crowdClap(0.6);
  }

  function perform(strip) {
    if (state !== 'play' || busy) return;
    const text = strip.textContent;
    setBusy(true);
    sfx.unlock();
    // strip flies to the mic
    const r = strip.getBoundingClientRect();
    const dx = W / 2 - (r.left + r.width / 2), dy = H * 0.4 - (r.top + r.height / 2);
    strip.classList.add('flying');
    strip.style.transform = `translate(${dx}px, ${dy}px) scale(0.3) rotate(25deg)`;
    setTimeout(() => { strip.remove(); if (state === 'play') { tray.appendChild(makeStrip(nextLine())); setBusy(busy); } }, 500);

    poem.push(text);
    bubble = { text, t: 0 };
    sayEl.textContent = text;
    jhave.talk = 1;
    jhave.moodT = 0;
    speak(text, () => {
      jhave.talk = 0;
      if (state !== 'play') return;
      react();
    });
  }

  function react() {
    const type = Math.random() < 0.5 ? 'hiss' : 'clap';
    const who = new Set(HIPSTERS.filter(() => Math.random() < 0.75));
    if (!who.size) who.add(HIPSTERS[0]);
    crowd = { type, t: 0, who };
    if (type === 'clap') {
      claps++;
      jhave.mood = 'smile';
      const words = ['*polite clapping*', '*snap snap snap*', 'mmm, yes.', '*golf clap*'];
      popCaption(words[Math.floor(Math.random() * words.length)], '#ffd23f', Math.min(38, W / 18));
      sfx.crowdClap(0.9);
    } else {
      hisses++;
      jhave.mood = 'grimace';
      const words = ['HISSSSS!', 'SSSSSSS!', '*disapproving sip*', 'derivative!'];
      popCaption(words[Math.floor(Math.random() * words.length)], '#7ad151', Math.min(44, W / 16));
      sfx.hiss();
    }
    clapsEl.textContent = claps;
    hissesEl.textContent = hisses;
    jhave.moodT = 1.6;
    setTimeout(() => {
      bubble = null;
      if (state === 'play') setBusy(false);
    }, 1300);
  }

  // Text-to-speech if the browser has it, otherwise a babble of bleeps
  let speechTimer = null;
  function speak(text, done) {
    let finished = false;
    const finish = () => {
      if (finished) return;
      finished = true;
      clearTimeout(speechTimer);
      done();
    };
    const maxMs = Math.min(7000, 900 + text.length * 85);
    speechTimer = setTimeout(() => { try { window.speechSynthesis && window.speechSynthesis.cancel(); } catch {} finish(); }, maxMs);
    try {
      if (window.speechSynthesis && window.SpeechSynthesisUtterance) {
        const u = new SpeechSynthesisUtterance(text);
        u.rate = 0.9;
        u.pitch = 0.8;
        u.lang = 'en-US';
        u.onend = finish;
        u.onerror = () => { sfx.babble(text); };
        window.speechSynthesis.cancel();
        window.speechSynthesis.speak(u);
        return;
      }
    } catch {}
    sfx.babble(text);
  }

  function beginFinale() {
    if (state !== 'play') return;
    state = 'finale';
    finaleAt = performance.now();
    clearTimeout(speechTimer);
    try { window.speechSynthesis && window.speechSynthesis.cancel(); } catch {}
    setBusy(true);
    tray.innerHTML = '';
    bubble = null;
    jhave.talk = 0;
    jhave.mood = 'smile';
    jhave.moodT = 99;
    crowd = { type: 'clap', t: 0, who: new Set(HIPSTERS), forever: true };
    sfx.stopBand();
    sfx.fanfare();

    const sub = poem.length
      ? `${poem.length}-line poem • ${claps} polite clap${claps === 1 ? '' : 's'} • ${hisses} hiss${hisses === 1 ? '' : 'es'} • winner anyway`
      : 'Jhave stood in silence for 55 seconds. The crowd called it brave.';
    resultText = poem.length
      ? `Jhave performed a ${poem.length}-line poem (${claps} claps, ${hisses} hisses) and won the slam anyway`
      : 'Jhave stood in silence for 55 seconds; the crowd called it brave. Winner!';
    $('finale-sub').textContent = sub;
    const ol = $('poem');
    ol.innerHTML = '';
    for (const l of poem) {
      const li = document.createElement('li');
      li.textContent = l;
      ol.appendChild(li);
    }
    finaleEl.hidden = false;
    for (let k = 0; k < 160; k++) {
      confetti.push({
        x: Math.random() * W, y: -Math.random() * H * 0.5,
        vx: (Math.random() - 0.5) * 60, vy: 80 + Math.random() * 160,
        r: Math.random() * Math.PI, vr: (Math.random() - 0.5) * 8,
        c: ['#ffd23f', '#e8452c', '#1aa39a', '#f6a5c0', '#fffbea'][k % 5]
      });
    }
  }

  function finish(success, result) {
    if (ended) return;
    ended = true;
    state = 'over';
    window.parent.postMessage({ type: 'defrag:complete', success, result }, '*');
  }

  // ---- Host protocol ----
  window.addEventListener('message', (event) => {
    const data = event.data;
    if (!data || typeof data !== 'object') return;
    if (data.type === 'defrag:start') startGame();
    if (data.type === 'defrag:timeout' && !ended) {
      if (state === 'play') beginFinale();
      finish(true, resultText || 'Jhave won the slam anyway');
    }
  });

  if (standalone) titleCard.addEventListener('click', startGame);

  // ---- Sound ----
  const sfx = (() => {
    let ac = null, band = null;
    function audio() {
      if (!ac) {
        try { ac = new (window.AudioContext || window.webkitAudioContext)(); } catch { return null; }
      }
      return ac;
    }
    function noise(a, secs) {
      const b = a.createBuffer(1, Math.max(1, a.sampleRate * secs), a.sampleRate);
      const d = b.getChannelData(0);
      for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
      return b;
    }
    function burst(t, dur, freq, q, vol, type = 'bandpass') {
      const a = ac;
      const s = a.createBufferSource(); s.buffer = noise(a, dur);
      const f = a.createBiquadFilter(); f.type = type; f.frequency.value = freq; f.Q.value = q;
      const g = a.createGain();
      g.gain.setValueAtTime(vol, t);
      g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      s.connect(f).connect(g).connect(a.destination);
      s.start(t);
    }
    function pluck(t, freq, dur, vol, type = 'triangle') {
      const a = ac;
      const o = a.createOscillator(), g = a.createGain(), f = a.createBiquadFilter();
      o.type = type; o.frequency.value = freq;
      f.type = 'lowpass'; f.frequency.value = 700;
      g.gain.setValueAtTime(vol, t);
      g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      o.connect(f).connect(g).connect(a.destination);
      o.start(t); o.stop(t + dur + 0.05);
    }
    // ii-V-I walking bass in F, plus brushes on 2 and 4
    const WALK = [98.0, 110.0, 116.5, 130.8, 130.8, 123.5, 110.0, 98.0, 87.3, 98.0, 110.0, 116.5, 87.3, 73.4, 77.8, 82.4];
    return {
      unlock() { const a = audio(); if (a && a.state === 'suspended') a.resume().catch(() => {}); },
      startBand() {
        const a = audio();
        if (!a || band) return;
        const beat = 0.48;
        let next = a.currentTime + 0.1, i = 0;
        band = setInterval(() => {
          if (a.state !== 'running') return;
          while (next < a.currentTime + 0.3) {
            pluck(next, WALK[i % WALK.length], beat * 0.9, 0.18);
            if (i % 2 === 1) burst(next, 0.18, 6000, 0.7, 0.03, 'highpass');
            next += beat; i++;
          }
        }, 80);
      },
      stopBand() { clearInterval(band); band = null; },
      crowdClap(amount) {
        const a = audio();
        if (!a || a.state !== 'running') return;
        const n = Math.round(14 * amount);
        for (let k = 0; k < n; k++) burst(a.currentTime + Math.random() * 1.1, 0.06, 1400 + Math.random() * 900, 1.2, 0.25);
      },
      hiss() {
        const a = audio();
        if (!a || a.state !== 'running') return;
        const t = a.currentTime;
        const s = a.createBufferSource(); s.buffer = noise(a, 1.6);
        const f = a.createBiquadFilter(); f.type = 'highpass'; f.frequency.value = 3500;
        const g = a.createGain();
        g.gain.setValueAtTime(0.0001, t);
        g.gain.exponentialRampToValueAtTime(0.16, t + 0.2);
        g.gain.exponentialRampToValueAtTime(0.0001, t + 1.5);
        s.connect(f).connect(g).connect(a.destination);
        s.start(t);
      },
      babble(text) {
        const a = audio();
        if (!a || a.state !== 'running') return;
        const syl = Math.min(18, Math.max(3, Math.round(text.length / 4)));
        for (let k = 0; k < syl; k++) {
          const t = a.currentTime + k * 0.13;
          const o = a.createOscillator(), g = a.createGain();
          o.type = 'square'; o.frequency.value = 140 + Math.random() * 90;
          g.gain.setValueAtTime(0.05, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.11);
          o.connect(g).connect(a.destination); o.start(t); o.stop(t + 0.12);
        }
      },
      fanfare() {
        const a = audio();
        if (!a || a.state !== 'running') return;
        const t = a.currentTime;
        for (let k = 0; k < 24; k++) burst(t + k * 0.04, 0.05, 300, 1, 0.12); // drumroll
        burst(t + 1.0, 1.2, 5000, 0.5, 0.2, 'highpass');                    // cymbal
        for (let k = 0; k < 40; k++) burst(t + 1.0 + Math.random() * 3, 0.06, 1500 + Math.random() * 800, 1.2, 0.25);
      }
    };
  })();

  // ---- Main loop ----
  let last = performance.now();
  let time = 0;
  function frame(now) {
    const dt = Math.min(0.05, (now - last) / 1000);
    last = now;
    time += dt;

    if (state === 'play') {
      const left = Math.max(0, SET_LENGTH - (now - startAt) / 1000);
      clockEl.textContent = `0:${String(Math.ceil(left)).padStart(2, '0')}`;
      if (left <= 0) beginFinale();
    } else if (state === 'finale') {
      clockEl.textContent = '0:00';
      if ((now - finaleAt) / 1000 >= FINALE_HOLD) finish(true, resultText);
    }

    jhave.jaw = jhave.talk > 0 ? Math.abs(Math.sin(time * 16)) * (0.6 + 0.4 * Math.sin(time * 5)) : Math.max(0, jhave.jaw - dt * 6);
    if (jhave.moodT > 0 && jhave.moodT < 50) jhave.moodT -= dt;
    if (bubble) bubble.t += dt;
    if (crowd) { crowd.t += dt; if (!crowd.forever && crowd.t > 1.6) crowd = null; }

    ctx.drawImage(backdrop, 0, 0, W, H);
    drawLights(time);
    drawSpotlight();
    const head = drawJhave(time);
    drawBubble(head);
    drawCrowd(time);
    drawCaptions(dt);

    for (const c of confetti) {
      c.x += c.vx * dt; c.y += c.vy * dt; c.r += c.vr * dt;
      if (c.y > H + 10) { c.y = -10; c.x = Math.random() * W; }
      ctx.save();
      ctx.translate(c.x, c.y); ctx.rotate(c.r);
      ctx.fillStyle = c.c;
      ctx.fillRect(-5, -3, 10, 6);
      ctx.restore();
    }

    requestAnimationFrame(frame);
  }

  // ---- Boot ----
  window.addEventListener('resize', resize);
  resize();
  faces.smile = cartoonFace(false);
  faces.grimace = cartoonFace(true);
  loadFaces();
  requestAnimationFrame(frame);
})();
